        Object.values(d.inc).forEach(list => list.forEach(it => keep.push(posOf(it))));
        let sd = 23; const r = () => { sd = (sd * 16807) % 2147483647; return sd / 2147483647; };
        for (let i = 0; i < 400 && out.length < 30; i++) { const p = [r() * 1.9 - 0.95, r() * 1.9 - 0.95]; if (keep.every(k => Math.hypot(p[0] - k[0], p[1] - k[1]) > 0.33)) out.push(p); }
        return out;
