      const ansOf = q => { const d = D(); if (q.pers) return d.pers.ans[q.user] || d.pers.ans['Борис']; if (S.scn === 'stale' && q.key === d.stale.key) return d.stale.newA; const e = d.ents.find(x => x.key === q.key); return e ? e.a : q.ans || ''; };

